window.__SHB_EGYPTIAN_BOOK_QUESTIONS__=(window.__SHB_EGYPTIAN_BOOK_QUESTIONS__||[]).concat([{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q61","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Hepatology / hepatitis B serology","q":"Australiaantigenis","o":["SurfaceantigenofthehepatitisBvirus","CoreantigenofthehepatitisBvirus","SurfaceantigenofhepatitisA","CoreantigenofhepatitisA"],"ol":["A","B","C","D"],"k":0,"ex":"“Australia antigen” is the historical name for hepatitis B surface antigen (HBsAg). Its presence indicates current HBV infection (acute or chronic); persistence for six months or more supports chronic infection.","more":"“Australia antigen” is the historical name for hepatitis B surface antigen (HBsAg). Its presence indicates current HBV infection (acute or chronic); persistence for six months or more supports chronic infection. **Why the others are wrong:** (a) Surface antigen of hepatitis B virus: correct. (b) Core antigen of HBV: incorrect; this is HBcAg. (c) Surface antigen of hepatitis A: incorrect; HAV has no analogous HBsAg. (d) Core antigen of hepatitis A: incorrect.\n\nCurriculum alignment: Pediatric hepatology 2024 section: hepatitis B serology and infection markers. **High-yield point / Review Notes:** HBsAg is a surface marker; anti-HBc and anti-HBs have different diagnostic meanings.\n\nHigh-yield point: “Australia antigen” is the historical name for hepatitis B surface antigen (HBsAg).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q61 — Hepatology / hepatitis B serology","aoSource":"Question-bank MD p.158 · printed p.308 · answer-key PDF p.169 · original Q61","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q001","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Manifestationsofgastroesophagealreflexare,except","o":["Respiratoryinfection","Loosemotion","Failuretothrive","Anaemia"],"ol":["A","B","C","D"],"k":1,"ex":"Gastroesophageal reflux (GER) is common in infancy. It becomes gastroesophageal reflux disease (GERD) when it causes troublesome symptoms or complications. Poor weight gain/failure to thrive and esophagitis with bleeding or iron-deficiency anemia may occur in significant GERD; recurrent aspiration or wheeze can occur in selected children, although respiratory symptoms are nonspecific and should not automatically be attributed to reflux. Loose stool is not a typical GERD manifestation, so option b is the intended exception.","more":"Gastroesophageal reflux (GER) is common in infancy. It becomes gastroesophageal reflux disease (GERD) when it causes troublesome symptoms or complications. Poor weight gain/failure to thrive and esophagitis with bleeding or iron-deficiency anemia may occur in significant GERD; recurrent aspiration or wheeze can occur in selected children, although respiratory symptoms are nonspecific and should not automatically be attributed to reflux. Loose stool is not a typical GERD manifestation, so option b is the intended exception.\n\nCurriculum alignment: GIT 2024–2025, pp.6–9: GER/GERD definitions, infant and older-child manifestations, complications and assessment.\n\nHigh-yield point: Distinguish uncomplicated infant regurgitation from GERD; recurrent respiratory complaints alone do not establish reflux disease.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q001 — Q1: Manifestations of gastroesophageal reflux: exception","aoSource":"Question-bank MD page 129 · Printed page 237 · Answer-key PDF page 137 · Original question Q1","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q002","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Congenitalhypertrophicpyloricstenosisusuallypresent atage","o":["1weeks","2-3weeks","5-6weeks","1-2months"],"ol":["A","B","C","D"],"k":1,"ex":"Hypertrophic pyloric stenosis usually presents during early infancy, classically at 2–8 weeks, with a peak around 2–3 weeks. Progressive projectile, non-bilious vomiting after feeds is typical; the infant often remains hungry after vomiting. The source-key answer 2–3 weeks is consistent with the lecture.","more":"Hypertrophic pyloric stenosis usually presents during early infancy, classically at 2–8 weeks, with a peak around 2–3 weeks. Progressive projectile, non-bilious vomiting after feeds is typical; the infant often remains hungry after vomiting. The source-key answer 2–3 weeks is consistent with the lecture.\n\nCurriculum alignment: GIT 2024–2025, pp.12–14: infantile pyloric stenosis, epidemiology and clinical presentation.\n\nHigh-yield point: Hypertrophic pyloric stenosis usually presents during early infancy, classically at 2–8 weeks, with a peak around 2–3 weeks.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q002 — Q2: Usual age at presentation of congenital hypertrophic pyloric stenosis","aoSource":"Question-bank MD page 129 · Printed page 237 · Answer-key PDF page 137 · Original question Q2","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q004","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Management","q":"The treatment of choice of the congenital hypertrophicpyloricstenosis","o":["Cimetidine","Ramstedtoperation","Cisapride","Intravenousfluid"],"ol":["A","B","C","D"],"k":1,"ex":"Definitive treatment is Ramstedt extramucosal pyloromyotomy. Before surgery, correct dehydration, hypochloremia, hypokalemia and metabolic alkalosis; surgery should not proceed before adequate fluid and electrolyte stabilization. Intravenous fluids are essential initial supportive care, but are not definitive treatment.","more":"Definitive treatment is Ramstedt extramucosal pyloromyotomy. Before surgery, correct dehydration, hypochloremia, hypokalemia and metabolic alkalosis; surgery should not proceed before adequate fluid and electrolyte stabilization. Intravenous fluids are essential initial supportive care, but are not definitive treatment.\n\nCurriculum alignment: GIT 2024–2025, pp.12–14: investigation, stabilization and Ramstedt pyloromyotomy.\n\nHigh-yield point: Definitive treatment is Ramstedt extramucosal pyloromyotomy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q004 — Q4: Treatment of choice for congenital hypertrophic pyloric stenosis","aoSource":"Question-bank MD page 129 · Printed page 237 · Answer-key PDF page 137 · Original question Q4","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q005","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Medical treatment is indicated in congenital hypertrophicpyloricstenosis","o":["Pylorospasm","Stenosis","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"The distinction is between functional pylorospasm and anatomical hypertrophic pyloric stenosis. Pylorospasm may be managed conservatively/medically after assessing the infant and excluding fixed obstruction. Hypertrophic pyloric stenosis is a structural obstruction and is treated definitively by pyloromyotomy after fluid and electrolyte correction.","more":"The distinction is between functional pylorospasm and anatomical hypertrophic pyloric stenosis. Pylorospasm may be managed conservatively/medically after assessing the infant and excluding fixed obstruction. Hypertrophic pyloric stenosis is a structural obstruction and is treated definitively by pyloromyotomy after fluid and electrolyte correction.\n\nCurriculum alignment: GIT 2024–2025, pp.12–14: hypertrophic pyloric stenosis and its surgical management; interpretation of the distinction from functional pylorospasm.\n\nHigh-yield point: The stem uses “congenital” loosely; pylorospasm and hypertrophic pyloric stenosis should not be conflated.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q005 — Q5: Condition in which medical treatment is indicated: pylorospasm versus pyloric stenosis","aoSource":"Question-bank MD page 129 · Printed page 237 · Answer-key PDF page 137 · Original question Q5","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q010","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thecentralnervoussystem causeoftheabdominal pain","o":["Abdominalepilepsy","Encephalitis","Meningitis","Reye'ssyndrome"],"ol":["A","B","C","D"],"k":0,"ex":"Abdominal epilepsy is an uncommon epilepsy presentation in which episodic abdominal pain or other gastrointestinal sensations occur as part of a seizure, sometimes with altered awareness or other ictal features. It is clinically relevant but rare and requires careful exclusion of common gastrointestinal, urinary, metabolic and surgical causes. The answer key selects abdominal epilepsy.","more":"Abdominal epilepsy is an uncommon epilepsy presentation in which episodic abdominal pain or other gastrointestinal sensations occur as part of a seizure, sometimes with altered awareness or other ictal features. It is clinically relevant but rare and requires careful exclusion of common gastrointestinal, urinary, metabolic and surgical causes. The answer key selects abdominal epilepsy.\n\nCurriculum alignment: GIT 2024–2025, p.51: medical causes in the differential diagnosis of acute abdominal pain; CNS/metabolic link is an educational extension.\n\nHigh-yield point: Extended Beyond Core Curriculum: abdominal epilepsy is rare and not described as a core topic in the supplied GIT lecture.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q010 — Q10: Central nervous system cause of abdominal pain","aoSource":"Question-bank MD page 130 · Printed page 238 · Answer-key PDF page 137 · Original question Q10","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q011","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thehaematologicalcauseoftheacuteabdominal pain","o":["Sicklecelldisease","Anaphylactoidpurpura","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Both sickle cell disease and IgA vasculitis (Henoch–Schönlein purpura; older term anaphylactoid purpura) can cause acute abdominal pain. Sickle cell disease can produce abdominal vaso-occlusive pain and complications; IgA vasculitis can cause bowel-wall edema, colicky pain, gastrointestinal bleeding and occasionally intussusception.","more":"Both sickle cell disease and IgA vasculitis (Henoch–Schönlein purpura; older term anaphylactoid purpura) can cause acute abdominal pain. Sickle cell disease can produce abdominal vaso-occlusive pain and complications; IgA vasculitis can cause bowel-wall edema, colicky pain, gastrointestinal bleeding and occasionally intussusception.\n\nCurriculum alignment: GIT 2024–2025, p.51: sickle cell disease and Henoch–Schönlein purpura appear among medical causes of acute abdominal pain; CNS/hematology content provides cross-topic context.\n\nHigh-yield point: Both sickle cell disease and IgA vasculitis (Henoch–Schönlein purpura; older term anaphylactoid purpura) can cause acute abdominal pain.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q011 — Q11: Hematological causes of acute abdominal pain","aoSource":"Question-bank MD page 130 · Printed page 238 · Answer-key PDF page 137 · Original question Q11","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q016","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thecausativeorganism ofthepseudomembranous colitis","o":["Campylobacterjejuni","Clostridiumdefficile","Yersenia","E.coli"],"ol":["A","B","C","D"],"k":1,"ex":"Pseudomembranous colitis is classically caused by toxin-producing Clostridioides difficile (older name Clostridium difficile), often following antibiotic exposure or healthcare contact. Toxins A and B injure colonic epithelium and produce adherent pseudomembranes.","more":"Pseudomembranous colitis is classically caused by toxin-producing Clostridioides difficile (older name Clostridium difficile), often following antibiotic exposure or healthcare contact. Toxins A and B injure colonic epithelium and produce adherent pseudomembranes.\n\nCurriculum alignment: GIT 2024–2025, pp.17–21: acute diarrhea, gastroenteritis and infectious causes; the source topic is clinically appropriate.\n\nHigh-yield point: Pseudomembranous colitis is classically caused by toxin-producing Clostridioides difficile (older name Clostridium difficile), often following antibiotic exposure or healthcare contact.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q016 — Q16: Causative organism of pseudomembranous colitis","aoSource":"Question-bank MD page 130 · Printed page 238 · Answer-key PDF page 137 · Original question Q16","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q020","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Prevention","q":"Breastmilkpreventsintestinalinfectionby","o":["IgA","Lactoferrin","Lactobacillusbifida","Alloftheabove"],"ol":["A","B","C","D"],"k":3,"ex":"Human milk protects against intestinal infection through several complementary mechanisms. Secretory IgA limits pathogen adherence and neutralizes antigens; lactoferrin binds iron and has antimicrobial/immune-modulating effects; human-milk oligosaccharides act as prebiotics and decoy receptors that support beneficial microbiota such as bifidobacteria. The older term “Lactobacillus bifida” is imprecise/outdated, but the intended concept is the bifidus-promoting intestinal flora.","more":"Human milk protects against intestinal infection through several complementary mechanisms. Secretory IgA limits pathogen adherence and neutralizes antigens; lactoferrin binds iron and has antimicrobial/immune-modulating effects; human-milk oligosaccharides act as prebiotics and decoy receptors that support beneficial microbiota such as bifidobacteria. The older term “Lactobacillus bifida” is imprecise/outdated, but the intended concept is the bifidus-promoting intestinal flora.\n\nCurriculum alignment: GIT 2024–2025, p.21: post-gastroenteritis and food-intolerance content; Growth and Nutrition source: breastfeeding and infant nutrition concepts.\n\nHigh-yield point: Terminology note: “Lactobacillus bifida” should not be silently modernized in the original stem; the explanation uses the current bifidobacterial terminology.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q020 — Q20: Protective factors in breast milk against intestinal infection","aoSource":"Question-bank MD page 130 · Printed page 238 · Answer-key PDF page 137 · Original question Q20","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q021","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"The common type of the electrolyte acid-base disturbanceinacutediarrhea,except","o":["Hyponatraemia","Hypokalaemia","Acidosis","Alkalosis"],"ol":["A","B","C","D"],"k":3,"ex":"Diarrheal stool losses commonly produce potassium and bicarbonate losses, leading to hypokalemia and metabolic acidosis. Sodium may also fall depending on the type and volume of fluid replacement and ongoing losses. Metabolic alkalosis is not the usual uncomplicated diarrheal pattern; it is more typical of substantial gastric acid loss, such as persistent vomiting.","more":"Diarrheal stool losses commonly produce potassium and bicarbonate losses, leading to hypokalemia and metabolic acidosis. Sodium may also fall depending on the type and volume of fluid replacement and ongoing losses. Metabolic alkalosis is not the usual uncomplicated diarrheal pattern; it is more typical of substantial gastric acid loss, such as persistent vomiting.\n\nCurriculum alignment: GIT 2024–2025, pp.17–18 and 22–27: diarrhea, dehydration, electrolyte loss and fluid management.\n\nHigh-yield point: Diarrheal stool losses commonly produce potassium and bicarbonate losses, leading to hypokalemia and metabolic acidosis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q021 — Q21: Typical electrolyte and acid–base disturbance in acute diarrhea: exception","aoSource":"Question-bank MD page 131 · Printed page 239 · Answer-key PDF page 137 · Original question Q21","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q024","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"ThecompositionofWHOORS,except-perlitreof water","o":["Sodiumchloride3.5g","Sodiumbicarbonate2.5g","Potassiumchloride1.5g","Glucose50g"],"ol":["A","B","C","D"],"k":3,"ex":"The first three listed quantities match the classic older WHO ORS formulation per litre: sodium chloride 3.5 g, sodium bicarbonate 2.5 g and potassium chloride 1.5 g. The old formula used 20 g glucose per litre, not 50 g. Current WHO reduced-osmolarity ORS is different again: approximately 2.6 g sodium chloride, 2.9 g trisodium citrate, 1.5 g potassium chloride and 13.5 g anhydrous glucose per litre. Therefore option d is the exception in this set.","more":"The first three listed quantities match the classic older WHO ORS formulation per litre: sodium chloride 3.5 g, sodium bicarbonate 2.5 g and potassium chloride 1.5 g. The old formula used 20 g glucose per litre, not 50 g. Current WHO reduced-osmolarity ORS is different again: approximately 2.6 g sodium chloride, 2.9 g trisodium citrate, 1.5 g potassium chloride and 13.5 g anhydrous glucose per litre. Therefore option d is the exception in this set.\n\nCurriculum alignment: GIT 2024–2025, pp.26–27: ORS and fluid management; the lecture lists both older and newer formulae. WHO, Oral Rehydration Salts: Production of the New ORS (2006), https://iris.who.int/bitstream/10665/69227/1/WHO_FCH_CAH_06.1.pdf.\n\nHigh-yield point: High-yield: always identify whether the question asks the older sodium-bicarbonate ORS or current reduced-osmolarity citrate ORS; the formulations are not interchangeable.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q024 — Q24: WHO oral rehydration solution composition: incorrect component","aoSource":"Question-bank MD page 131 · Printed page 239 · Answer-key PDF page 137 · Original question Q24","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q028","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Pharmacology","q":"Metronidazoleisthedrugofthechoice","o":["Bacterialinfection","Anaerobicbacterialinfection","Aerobicbacterialinfection","Viralinfection"],"ol":["A","B","C","D"],"k":1,"ex":"Metronidazole is active against obligate anaerobic bacteria and several protozoa. It is not a general treatment for aerobic bacterial infections and has no activity against viruses. Choice of antibiotic for an actual patient depends on the suspected site, organism, severity and local guidance.","more":"Metronidazole is active against obligate anaerobic bacteria and several protozoa. It is not a general treatment for aerobic bacterial infections and has no activity against viruses. Choice of antibiotic for an actual patient depends on the suspected site, organism, severity and local guidance.\n\nCurriculum alignment: GIT 2024–2025, pp.19–21 and chronic diarrhea/giardiasis sections: infectious gastrointestinal disease and antiparasitic treatment.\n\nHigh-yield point: Metronidazole is active against obligate anaerobic bacteria and several protozoa.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q028 — Q28: Antimicrobial spectrum of metronidazole","aoSource":"Question-bank MD page 131 · Printed page 239 · Answer-key PDF page 137 · Original question Q28","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q030","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Management","q":"Bindingandantimotilitydrugsshouldnottobeused ingastrointestinaltractinfectionbecause","o":["Dangerofthebacterialstasis","Absorptiontoxins","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"In infectious diarrhea, drugs that slow intestinal transit or suppress motility may prolong contact with pathogens or toxins and can worsen ileus or complications in invasive/inflammatory diarrhea. In children with acute diarrhea, loperamide should generally be avoided; oral rehydration and appropriate cause-specific management are the priorities. “Binding” agents are not substitutes for rehydration.","more":"In infectious diarrhea, drugs that slow intestinal transit or suppress motility may prolong contact with pathogens or toxins and can worsen ileus or complications in invasive/inflammatory diarrhea. In children with acute diarrhea, loperamide should generally be avoided; oral rehydration and appropriate cause-specific management are the priorities. “Binding” agents are not substitutes for rehydration.\n\nCurriculum alignment: GIT 2024–2025, pp.22–27: management of gastroenteritis and dehydration. IDSA infectious diarrhea guideline, https://www.idsociety.org/practice-guideline/infectious-diarrhea/.\n\nHigh-yield point: In infectious diarrhea, drugs that slow intestinal transit or suppress motility may prolong contact with pathogens or toxins and can worsen ileus or complications in invasive/inflammatory diarrhea.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q030 — Q30: Why binding/antimotility drugs are avoided in gastrointestinal infection","aoSource":"Question-bank MD page 131 · Printed page 239 · Answer-key PDF page 137 · Original question Q30","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q032","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Suspicion of the lactose intolerance by stool examination","o":["Presenceofreducingsubstance","pHlessthan5.5","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Undigested lactose is fermented by colonic bacteria, producing organic acids and an osmotic load. In infants/young children with carbohydrate malabsorption, stool may be acidic (classically pH below about 5.5–6) and may contain reducing substances. These are supportive screening findings rather than a lactose-specific definitive diagnosis; age, recent gastroenteritis and other carbohydrate malabsorption can affect interpretation.","more":"Undigested lactose is fermented by colonic bacteria, producing organic acids and an osmotic load. In infants/young children with carbohydrate malabsorption, stool may be acidic (classically pH below about 5.5–6) and may contain reducing substances. These are supportive screening findings rather than a lactose-specific definitive diagnosis; age, recent gastroenteritis and other carbohydrate malabsorption can affect interpretation.\n\nCurriculum alignment: GIT 2024–2025, pp.32–38 and chronic diarrhea sections: food intolerance, lactose intolerance and osmotic diarrhea. NASPGHAN Foundation, Diagnosis and Management of Carbohydrate-Induced Diarrhea, https://www.naspghan.org/files/documents/pdfs/Locked%20Diagnosis%20and%20Management%20of%20Carbohydrate-Induced%20Diarrhea%20final%2019%20Feb%202013.pdf.\n\nHigh-yield point: Supportive screening tests are not specific; use clinical response and, when appropriate, a hydrogen breath test or other evaluation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q032 — Q32: Stool findings that suggest lactose intolerance","aoSource":"Question-bank MD page 131 · Printed page 239 · Answer-key PDF page 137 · Original question Q32","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q033","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Thelaboratorytestotherthanstoolwillclinchthe lactoseintolerance","o":["Hydrogenbreathtest","Sweattest","D-xylosetest","None"],"ol":["A","B","C","D"],"k":0,"ex":"A lactose hydrogen breath test detects increased exhaled hydrogen after an oral lactose load, reflecting bacterial fermentation of lactose that was not absorbed in the small bowel. It is a widely used non-invasive test, interpreted alongside symptoms and test protocol. Stool pH/reducing substances are different screening tests.","more":"A lactose hydrogen breath test detects increased exhaled hydrogen after an oral lactose load, reflecting bacterial fermentation of lactose that was not absorbed in the small bowel. It is a widely used non-invasive test, interpreted alongside symptoms and test protocol. Stool pH/reducing substances are different screening tests.\n\nCurriculum alignment: GIT 2024–2025, pp.32–38: lactose intolerance and chronic diarrhea; European hydrogen/methane breath-test consensus, https://pmc.ncbi.nlm.nih.gov/articles/PMC8830282/.\n\nHigh-yield point: A lactose hydrogen breath test detects increased exhaled hydrogen after an oral lactose load, reflecting bacterial fermentation of lactose that was not absorbed in the small bowel.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q033 — Q33: Laboratory test used to support diagnosis of lactose intolerance","aoSource":"Question-bank MD page 132 · Printed page 240 · Answer-key PDF page 137 · Original question Q33","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q045","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"The enzyme concerned with the conjugation of bilirubin","o":["αltrypsin","Glucoronyltransferee","Both","None"],"ol":["A","B","C","D"],"k":1,"ex":"Hepatic bilirubin is conjugated with glucuronic acid by UDP-glucuronosyltransferase (UGT1A1), making bilirubin more water-soluble so it can be excreted into bile. Deficiency or absent activity causes unconjugated hyperbilirubinemia, as in Crigler–Najjar syndrome. The source transcription spells the option “Glucoronyltransferee”; the intended enzyme is glucuronyl transferase.","more":"Hepatic bilirubin is conjugated with glucuronic acid by UDP-glucuronosyltransferase (UGT1A1), making bilirubin more water-soluble so it can be excreted into bile. Deficiency or absent activity causes unconjugated hyperbilirubinemia, as in Crigler–Najjar syndrome. The source transcription spells the option “Glucoronyltransferee”; the intended enzyme is glucuronyl transferase.\n\nCurriculum alignment: Neonatology 2024–2025, pp.43–47: bilirubin metabolism, hepatic conjugation and Crigler–Najjar syndrome; Pediatric hepatology pp.17–18 for liver disease context.\n\nHigh-yield point: Hepatic bilirubin is conjugated with glucuronic acid by UDP-glucuronosyltransferase (UGT1A1), making bilirubin more water-soluble so it can be excreted into bile.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q045 — Q45: Enzyme responsible for bilirubin conjugation","aoSource":"Question-bank MD page 132 · Printed page 240 · Answer-key PDF page 137 · Original question Q45","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q046","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Congenitaldiseasecausingdirectbilirubinaemia","o":["Dubin-Johnsonsyndrome","Rotorsyndrome","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Dubin–Johnson syndrome and Rotor syndrome are inherited disorders associated with conjugated (direct) hyperbilirubinemia, generally without the same severe progressive hepatocellular injury seen in many other cholestatic diseases. Dubin–Johnson involves impaired canalicular excretion of conjugated bilirubin; Rotor syndrome involves hepatic uptake/storage transport defects.","more":"Dubin–Johnson syndrome and Rotor syndrome are inherited disorders associated with conjugated (direct) hyperbilirubinemia, generally without the same severe progressive hepatocellular injury seen in many other cholestatic diseases. Dubin–Johnson involves impaired canalicular excretion of conjugated bilirubin; Rotor syndrome involves hepatic uptake/storage transport defects.\n\nCurriculum alignment: Neonatology 2024–2025, p.52: metabolic/genetic causes of conjugated hyperbilirubinemia, explicitly listing Rotor and Dubin–Johnson syndromes.\n\nHigh-yield point: Dubin–Johnson syndrome and Rotor syndrome are inherited disorders associated with conjugated (direct) hyperbilirubinemia, generally without the same severe progressive hepatocellular injury seen in many other cholestatic diseases.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q046 — Q46: Congenital disorders causing direct hyperbilirubinemia","aoSource":"Question-bank MD page 133 · Printed page 241 · Answer-key PDF page 137 · Original question Q46","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q047","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Congenitaldiseasecausingindirectbilirubinaemia","o":["Criggler-Najhardisease","Dubin-Johnsondisease","Rotorsyndrome","None"],"ol":["A","B","C","D"],"k":0,"ex":"Crigler–Najjar syndrome results from absent (type I) or markedly reduced (type II) UGT1A1 activity, impairing bilirubin conjugation and causing unconjugated/indirect hyperbilirubinemia. Dubin–Johnson and Rotor syndromes cause conjugated hyperbilirubinemia instead.","more":"Crigler–Najjar syndrome results from absent (type I) or markedly reduced (type II) UGT1A1 activity, impairing bilirubin conjugation and causing unconjugated/indirect hyperbilirubinemia. Dubin–Johnson and Rotor syndromes cause conjugated hyperbilirubinemia instead.\n\nCurriculum alignment: Neonatology 2024–2025, pp.44 and 47: causes of unconjugated hyperbilirubinemia and Crigler–Najjar types.\n\nHigh-yield point: Crigler–Najjar syndrome results from absent (type I) or markedly reduced (type II) UGT1A1 activity, impairing bilirubin conjugation and causing unconjugated/indirect hyperbilirubinemia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q047 — Q47: Congenital disorder causing indirect hyperbilirubinemia","aoSource":"Question-bank MD page 133 · Printed page 241 · Answer-key PDF page 137 · Original question Q47","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q049","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thecauseoftransudateasciticfluid","o":["Livercirrhosis","Nephroticsyndrome","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Cirrhosis can cause ascites through portal hypertension, renal sodium retention and reduced effective circulating volume. Nephrotic syndrome can cause ascites through severe hypoalbuminemia and altered Starling forces, often with sodium retention. Thus both can cause low-protein, traditionally “transudative” ascites. Modern ascites evaluation favors the serum–ascites albumin gradient (SAAG) and total protein rather than relying only on the transudate/exudate label; nephrotic ascites is usually low-SAAG/low-protein, whereas cirrhotic portal-hypertensive ascites is high-SAAG/low-protein.","more":"Cirrhosis can cause ascites through portal hypertension, renal sodium retention and reduced effective circulating volume. Nephrotic syndrome can cause ascites through severe hypoalbuminemia and altered Starling forces, often with sodium retention. Thus both can cause low-protein, traditionally “transudative” ascites. Modern ascites evaluation favors the serum–ascites albumin gradient (SAAG) and total protein rather than relying only on the transudate/exudate label; nephrotic ascites is usually low-SAAG/low-protein, whereas cirrhotic portal-hypertensive ascites is high-SAAG/low-protein.\n\nCurriculum alignment: Pediatric hepatology source, pp.15–16: cirrhosis, portal hypertension, low albumin and ascites; Nephrology 2024, nephrotic syndrome and edema/hypoalbuminemia. For modern fluid classification, SAAG is preferable to the old transudate/exudate terminology.\n\nHigh-yield point: Cirrhosis can cause ascites through portal hypertension, renal sodium retention and reduced effective circulating volume.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q049 — Q49: Causes of transudative ascites","aoSource":"Question-bank MD page 133 · Printed page 241 · Answer-key PDF page 137 · Original question Q49","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q050","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thecauseofexudationasciticfluid,except","o":["Tuberculosis","Malignancy","Nephrotic","Alloftheabove"],"ol":["A","B","C","D"],"k":2,"ex":"Peritoneal tuberculosis and malignant peritoneal involvement commonly produce protein-rich inflammatory or malignant ascites (often low SAAG and high protein). Nephrotic syndrome more typically causes ascites related to hypoalbuminemia, with low protein content, rather than inflammatory exudative ascites. Modern classification uses SAAG plus ascitic protein, not a binary exudate/transudate label alone.","more":"Peritoneal tuberculosis and malignant peritoneal involvement commonly produce protein-rich inflammatory or malignant ascites (often low SAAG and high protein). Nephrotic syndrome more typically causes ascites related to hypoalbuminemia, with low protein content, rather than inflammatory exudative ascites. Modern classification uses SAAG plus ascitic protein, not a binary exudate/transudate label alone.\n\nCurriculum alignment: Pediatric hepatology source, pp.15–16: ascites in chronic liver disease; Nephrology 2024: nephrotic syndrome and hypoalbuminemia. The detailed ascitic-fluid distinction extends beyond the supplied GIT lecture.\n\nHigh-yield point: Peritoneal tuberculosis and malignant peritoneal involvement commonly produce protein-rich inflammatory or malignant ascites (often low SAAG and high protein).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q050 — Q50: Cause of exudative ascites: exception","aoSource":"Question-bank MD page 133 · Printed page 241 · Answer-key PDF page 137 · Original question Q50","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q055","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Bloodandmucusinstoolsareseeninall,except","o":["E.histolytica","E.coli","Shigelleshigae","Vibreocholerae"],"ol":["A","B","C","D"],"k":3,"ex":"Blood and mucus in stool suggest inflammatory or invasive intestinal disease, including amoebic dysentery, Shigella and selected diarrheagenic E. coli pathotypes (for example Shiga toxin-producing or enteroinvasive strains). Cholera classically causes profuse watery “rice-water” diarrhea rather than a dysenteric blood-and-mucus stool. “E. coli” is a broad category, so its clinical effect depends on pathotype.","more":"Blood and mucus in stool suggest inflammatory or invasive intestinal disease, including amoebic dysentery, Shigella and selected diarrheagenic E. coli pathotypes (for example Shiga toxin-producing or enteroinvasive strains). Cholera classically causes profuse watery “rice-water” diarrhea rather than a dysenteric blood-and-mucus stool. “E. coli” is a broad category, so its clinical effect depends on pathotype.\n\nCurriculum alignment: GIT 2024–2025, pp.17–21 and 44: watery versus bloody diarrhea and infectious causes.\n\nHigh-yield point: Blood and mucus in stool suggest inflammatory or invasive intestinal disease, including amoebic dysentery, Shigella and selected diarrheagenic E.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q055 — Q55: Causes of blood and mucus in stool: exception","aoSource":"Question-bank MD page 134 · Printed page 242 · Answer-key PDF page 137 · Original question Q55","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q056","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"The first and most common symptom of intussception","o":["AbdominalPain","Diarrhea","Vomiting","Abdominaldistension"],"ol":["A","B","C","D"],"k":0,"ex":"The typical early symptom of intussusception is sudden, intermittent, severe colicky abdominal pain, often with pallor, crying and drawing up of the legs. The child may appear relatively well or sleepy between episodes. Vomiting and abdominal distension may develop as obstruction progresses; red-currant-jelly stool is a characteristic but late and not universal sign.","more":"The typical early symptom of intussusception is sudden, intermittent, severe colicky abdominal pain, often with pallor, crying and drawing up of the legs. The child may appear relatively well or sleepy between episodes. Vomiting and abdominal distension may develop as obstruction progresses; red-currant-jelly stool is a characteristic but late and not universal sign.\n\nCurriculum alignment: GIT 2024–2025, pp.51 and 54–55: acute abdominal pain differential and intussusception presentation/pathophysiology.\n\nHigh-yield point: The typical early symptom of intussusception is sudden, intermittent, severe colicky abdominal pain, often with pallor, crying and drawing up of the legs.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q056 — Q56: First and most common symptom of intussusception","aoSource":"Question-bank MD page 134 · Printed page 242 · Answer-key PDF page 137 · Original question Q56","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q057","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Infectivediarrheaiscommonlydueto","o":["Pseudomonas","E.coli","Klebsiella","Staphaureus"],"ol":["A","B","C","D"],"k":1,"ex":"Escherichia coli includes multiple diarrheagenic pathotypes and is a major cause of infectious diarrhea worldwide. The exact pathogenic mechanism depends on the strain (enterotoxigenic, enteropathogenic, enteroaggregative, enteroinvasive or Shiga toxin-producing, among others). The other listed organisms can cause selected infections but are not the best general answer.","more":"Escherichia coli includes multiple diarrheagenic pathotypes and is a major cause of infectious diarrhea worldwide. The exact pathogenic mechanism depends on the strain (enterotoxigenic, enteropathogenic, enteroaggregative, enteroinvasive or Shiga toxin-producing, among others). The other listed organisms can cause selected infections but are not the best general answer.\n\nCurriculum alignment: GIT 2024–2025, pp.17–21: acute diarrhea and bacterial gastroenteritis.\n\nHigh-yield point: Escherichia coli includes multiple diarrheagenic pathotypes and is a major cause of infectious diarrhea worldwide.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q057 — Q57: Common bacterial cause of infectious diarrhea among the listed options","aoSource":"Question-bank MD page 134 · Printed page 242 · Answer-key PDF page 137 · Original question Q57","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q059","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Treatmentofgiardiasisis","o":["Mebandazole","Metronidazole","Piperzine","Bephenium"],"ol":["A","B","C","D"],"k":1,"ex":"Giardia duodenalis (G. lamblia) causes a protozoal small-intestinal infection that may produce persistent foul-smelling diarrhea, bloating, flatulence and malabsorption. Metronidazole is a traditional effective treatment and matches the source key; tinidazole and nitazoxanide are other current options in many settings. Drug choice and regimen depend on local availability, age and clinical context.","more":"Giardia duodenalis (G. lamblia) causes a protozoal small-intestinal infection that may produce persistent foul-smelling diarrhea, bloating, flatulence and malabsorption. Metronidazole is a traditional effective treatment and matches the source key; tinidazole and nitazoxanide are other current options in many settings. Drug choice and regimen depend on local availability, age and clinical context.\n\nCurriculum alignment: GIT 2024–2025, pp.32–38: chronic diarrhea and giardiasis; treatment options are appropriate clinically relevant knowledge.\n\nHigh-yield point: Giardia duodenalis (G.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q059 — Q59: Treatment of giardiasis","aoSource":"Question-bank MD page 134 · Printed page 242 · Answer-key PDF page 137 · Original question Q59","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q060","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Celiacdiseaseisduetosensitivityto","o":["Milk","Wheat","Maize","Meat"],"ol":["A","B","C","D"],"k":1,"ex":"Celiac disease is an immune-mediated enteropathy triggered by gluten in genetically susceptible individuals. Wheat contains gluten; barley and rye also contain related immunogenic prolamins. Maize and meat are naturally gluten-free. The source key “wheat” is correct among these options.","more":"Celiac disease is an immune-mediated enteropathy triggered by gluten in genetically susceptible individuals. Wheat contains gluten; barley and rye also contain related immunogenic prolamins. Maize and meat are naturally gluten-free. The source key “wheat” is correct among these options.\n\nCurriculum alignment: GIT 2024–2025, pp.32–38: celiac disease and chronic diarrhea.\n\nHigh-yield point: Celiac disease is an immune-mediated enteropathy triggered by gluten in genetically susceptible individuals.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q060 — Q60: Dietary antigen associated with celiac disease","aoSource":"Question-bank MD page 134 · Printed page 242 · Answer-key PDF page 137 · Original question Q60","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q063","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Which one ofthe following is associated with chronicliverdisease","o":["HepatitisA","Alpha-1antitrypsin","Malaria","Infectiousmononucleosis"],"ol":["A","B","C","D"],"k":1,"ex":"Alpha-1 antitrypsin deficiency is an inherited cause of pediatric liver disease. Misfolded alpha-1 antitrypsin can accumulate in hepatocytes, causing neonatal cholestasis, hepatitis, fibrosis and cirrhosis in some children; deficiency also predisposes to lung disease later in life. Hepatitis A is usually acute and self-limited, while malaria and infectious mononucleosis are not classic causes of chronic liver disease.","more":"Alpha-1 antitrypsin deficiency is an inherited cause of pediatric liver disease. Misfolded alpha-1 antitrypsin can accumulate in hepatocytes, causing neonatal cholestasis, hepatitis, fibrosis and cirrhosis in some children; deficiency also predisposes to lung disease later in life. Hepatitis A is usually acute and self-limited, while malaria and infectious mononucleosis are not classic causes of chronic liver disease.\n\nCurriculum alignment: Pediatric hepatology source, pp.17–18: causes of chronic liver disease in older children and α1-antitrypsin deficiency; Neonatology 2024–2025, p.52 also lists α-antitrypsin deficiency among cholestatic causes.\n\nHigh-yield point: Alpha-1 antitrypsin deficiency is an inherited cause of pediatric liver disease.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q063 — Q63: Association with chronic liver disease","aoSource":"Question-bank MD page 135 · Printed page 243 · Answer-key PDF page 137 · Original question Q63","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q072","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"The following is nottrue regarding the Wilson's disease","o":["Fanconisyndrome","Sensorychanges","Hemolyticanemia","Chronicactivehepatitis"],"ol":["A","B","C","D"],"k":1,"ex":"Wilson disease is an autosomal-recessive disorder of ATP7B-mediated copper handling, leading to copper accumulation in the liver, brain, kidneys and cornea. Pediatric manifestations include hepatitis/cirrhosis, Coombs-negative hemolytic anemia, renal tubular dysfunction including Fanconi syndrome, and later neuropsychiatric/extrapyramidal findings such as tremor, dysarthria and incoordination. “Sensory changes” is not a characteristic defining presentation among these options.","more":"Wilson disease is an autosomal-recessive disorder of ATP7B-mediated copper handling, leading to copper accumulation in the liver, brain, kidneys and cornea. Pediatric manifestations include hepatitis/cirrhosis, Coombs-negative hemolytic anemia, renal tubular dysfunction including Fanconi syndrome, and later neuropsychiatric/extrapyramidal findings such as tremor, dysarthria and incoordination. “Sensory changes” is not a characteristic defining presentation among these options.\n\nCurriculum alignment: Pediatric hepatology source, pp.17–18: Wilson disease, renal Fanconi syndrome, hemolysis and extrapyramidal features.\n\nHigh-yield point: Wilson disease is an autosomal-recessive disorder of ATP7B-mediated copper handling, leading to copper accumulation in the liver, brain, kidneys and cornea.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q072 — Q72: Statement not true about Wilson disease","aoSource":"Question-bank MD page 135 · Printed page 243 · Answer-key PDF page 137 · Original question Q72","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q073","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"Which ofthe following is the usualfeature of ascariasis","o":["Abdominalpain","Anemia","Urtecaria","Loffler'ssyndrome"],"ol":["A","B","C","D"],"k":0,"ex":"Ascaris lumbricoides infection is often asymptomatic or causes abdominal pain and gastrointestinal symptoms; heavy worm burden can cause intestinal obstruction. During larval migration through the lungs, transient eosinophilic pneumonitis (Löffler syndrome) may occur. Thus abdominal pain is a common usual intestinal symptom, while Löffler syndrome is a recognized but phase-specific pulmonary manifestation.","more":"Ascaris lumbricoides infection is often asymptomatic or causes abdominal pain and gastrointestinal symptoms; heavy worm burden can cause intestinal obstruction. During larval migration through the lungs, transient eosinophilic pneumonitis (Löffler syndrome) may occur. Thus abdominal pain is a common usual intestinal symptom, while Löffler syndrome is a recognized but phase-specific pulmonary manifestation.\n\nCurriculum alignment: GIT 2024–2025, pp.17–21: parasitic causes of diarrhea and intestinal disease; the question adds a relevant helminthic differential.\n\nHigh-yield point: Ascaris lumbricoides infection is often asymptomatic or causes abdominal pain and gastrointestinal symptoms; heavy worm burden can cause intestinal obstruction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q073 — Q73: Usual feature of ascariasis","aoSource":"Question-bank MD page 135 · Printed page 243 · Answer-key PDF page 137 · Original question Q73","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q078","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Livercirrhosisinchildhoodiscausedby","o":["Alpha-1antitrypsindeficiency","Coeliacdisease","Phenylketonuria","Cow'smilkintolerance"],"ol":["A","B","C","D"],"k":0,"ex":"Alpha-1 antitrypsin deficiency is a recognized inherited cause of chronic liver disease and cirrhosis in childhood. The abnormal protein may accumulate in hepatocytes and cause progressive hepatic injury. Celiac disease and cow’s-milk intolerance are not usual direct causes of cirrhosis, and phenylketonuria primarily causes neurodevelopmental and metabolic complications rather than being a typical childhood cirrhosis cause.","more":"Alpha-1 antitrypsin deficiency is a recognized inherited cause of chronic liver disease and cirrhosis in childhood. The abnormal protein may accumulate in hepatocytes and cause progressive hepatic injury. Celiac disease and cow’s-milk intolerance are not usual direct causes of cirrhosis, and phenylketonuria primarily causes neurodevelopmental and metabolic complications rather than being a typical childhood cirrhosis cause.\n\nCurriculum alignment: Pediatric hepatology source, pp.17–18: α1-antitrypsin deficiency as a cause of chronic liver disease in children.\n\nHigh-yield point: Alpha-1 antitrypsin deficiency is a recognized inherited cause of chronic liver disease and cirrhosis in childhood.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q078 — Q78: Cause of childhood cirrhosis among the listed options","aoSource":"Question-bank MD page 135 · Printed page 243 · Answer-key PDF page 137 · Original question Q78","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-gastroenterology-accepted-CH10-Q081","spec":"eb-gastroenterology","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"An infantwith severe dehydration secondary to diarrhoea presents with protein and blood in urine the most probablediagnosis","o":["Renalveinthrombosis","Acuteglomerulonephritis","Pyelonephritis","Lowernephrosis"],"ol":["A","B","C","D"],"k":0,"ex":"Severe dehydration and reduced renal perfusion can predispose infants to renal venous thrombosis. Renal vein thrombosis may present with hematuria, proteinuria, renal enlargement or a palpable mass, thrombocytopenia and renal dysfunction; dehydration is a recognized risk factor. The presentation still requires urgent evaluation because hematuria/proteinuria after diarrhea also has other differentials, including hemolytic uremic syndrome and glomerulonephritis.","more":"Severe dehydration and reduced renal perfusion can predispose infants to renal venous thrombosis. Renal vein thrombosis may present with hematuria, proteinuria, renal enlargement or a palpable mass, thrombocytopenia and renal dysfunction; dehydration is a recognized risk factor. The presentation still requires urgent evaluation because hematuria/proteinuria after diarrhea also has other differentials, including hemolytic uremic syndrome and glomerulonephritis.\n\nCurriculum alignment: Nephrology 2024, pp.17–20: renal disease, hematuria/proteinuria and nephrotic/nephritic differentials; GIT 2024–2025, pp.22–27: severe diarrheal dehydration.\n\nHigh-yield point: Source wording “Lower nephrosis” is retained; its intended meaning is unclear from the transcription.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH10-Q081 — Q81: Renal diagnosis after severe diarrheal dehydration with hematuria and proteinuria","aoSource":"Question-bank MD page 136 · Printed page 244 · Answer-key PDF page 137 · Original question Q81","aoSystem":"الجهاز الهضمي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Gastroenterology_Accepted.md","_genhy":false}]);
